def can_prevent_doof(test_cases):
    def gcd(a, b):
        if b == 0:
            return a
        return gcd(b, a % b)

    results = []

    for case in test_cases:
        N, A = case
        value = A[0]

        if N != 1:
            for i in A[1:]:
                value = value * i // gcd(value, i)

