    return results

def calculate_execution_time(N, calling_order, ideal_order):
    x = 0
    total_time = 0

    while x < N:
        if calling_order[x] == ideal_order[x]:
            x += 1
        else:
            temp = calling_order[x]
            for j in range(x + 1, N):
                calling_order[j - 1] = calling_order[j]
            calling_order[N - 1] = temp
        total_time += 1

