def calculate_minimum_resistors(a: int, b: int) -> int:
    def rec(a, b):
        ans = 0
        while True:
            if a == b:
                ans += 1
                break
            elif a == 0 or b == 0:
                break
            if a > b:
                k = (a - a % b) // b
                (a, b) = (a % b, b)
            elif a < b:
                k = (b - b % a) // a
                (a, b) = (a, b % a)
            ans += k
        return ans

    return rec(a, b)

def prefix_to_infix(pre_exp: str) -> str:
    stk = []
    i = len(pre_exp) - 1
    while i >= 0:
        if pre_exp[i] in ['+', '-', '*', '/', '^']:
            op1 = stk.pop()
            op2 = stk.pop()
            stk.append(f'({op1}{pre_exp[i]}{op2})')
        else:
            stk.append(pre_exp[i])
        i -= 1
    return stk.pop()

from collections import deque

def find_alien_order(dict, N, K):
    adj = [[] for _ in range(K)]
    for i in range(N - 1):
        s1 = dict[i]
        s2 = dict[i + 1]
        n = min(len(s1), len(s2))
        for j in range(n):
            if s1[j] != s2[j]:
                adj[ord(s1[j]) - ord('a')].append(ord(s2[j]) - ord('a'))
                break

    ind = [0] * K
    q = deque()
    for i in range(K):
        for it in adj[i]:
            ind[it] += 1

    for i in range(K):
        if ind[i] == 0:
            q.append(i)

    tpo = []
    while q:
        node = q.popleft()
        tpo.append(node)
        for child in adj[node]:
            ind[child] -= 1
            if ind[child] == 0:
                q.append(child)

    ans = ''
    for it in tpo:
        ans += chr(it + ord('a'))

    return ans

