def power_sum(X, N):
    def helper(num, total):
        powered_num = num ** N
        if powered_num == total:
            return 1
        if powered_num > total:
            return 0
        return helper(num + 1, total - powered_num) + helper(num + 1, total)

    return helper(1, X)

