        if messages[0][0] == '+' and messages[-1][0] == '-' and (messages[0][1] == messages[-1][1]) and continuos[messages[0][1]] and ultimo_en_salir[messages[0][1]]:
            posibles_jefes_mencionados.add(messages[0][1])
    elif not posteriores:
