    sorted_probabilities = sorted(probabilities, reverse=True)

    # If there's a 100% probability, Andrey won't get upset
    if 1.0 in sorted_probabilities:
        return 1.0

    # Initialize variables for the probability calculation
    a, b = 0, 1

    # Iterate through the sorted probabilities
    for p in sorted_probabilities:
        c = a + p / (1 - p)
        d = b * (1 - p)

        # Update if the new probability is better
        if c * d > a * b:
            a, b = c, d
        else:
