def min_palindrome_partitions(s: str) -> int:
    def is_palindrome(s, start, end):
        while start < end:
            if s[start] != s[end]:
                return False
            start += 1
            end -= 1
        return True

    def dfs(s, i, j, dp):
        if dp[i][j] != -1:
            return dp[i][j]
        if i >= j:
            return 0
        if is_palindrome(s, i, j):
            return 0
        mx = len(s)
        for k in range(i, j):
            if is_palindrome(s, i, k):
                t = dfs(s, k + 1, j, dp) + 1
                mx = min(mx, t)
        dp[i][j] = mx
        return dp[i][j]

    n = len(s)
    dp = [[-1] * (n + 1) for _ in range(n + 1)]
    return dfs(s, 0, n - 1, dp)

