def find_pi_fraction(allowed_error: float) -> tuple:
    n = d = 1
    while abs(n / d - pi) > allowed_error:
        if n / d < pi:
            n += 1
        else:
            d += 1
    return (n, d)

def calculate_max_correct_marching_percentage(sequence: str) -> float:
    def rate(seq: str) -> int:
        (correct, total, unknown, indicator) = (0, 0, 0, 0)
        left_step = True
        for action in seq:
            if action == 'X':
                total += 1
                left_step = not left_step
            elif (left_step and action == 'L') or (not left_step and action == 'R'):
                correct += 1
                total += 1
                indicator = 0
                left_step = not left_step
            else:
                correct += 1
                total += 2
                unknown += indicator
                indicator = 1 - indicator
        if total % 2 == 1:
            total += 1
            unknown += indicator
        if correct * 2 > total:
            correct -= unknown
            total -= unknown * 2
        return correct * 100000000 // total

    temp = [sequence[0]]
    for i in range(1, len(sequence)):
        if sequence[i] == sequence[i - 1] != 'X':
            temp.append('X')
        temp.append(sequence[i])
    augmented = ''.join(temp)
    answer = 0
    if augmented[0] == augmented[-1] != 'X':
        answer = max(rate(augmented + 'X'), rate('X' + augmented))
    else:
        answer = rate(augmented)
    return float(f'{answer / 1000000:.6f}')

import math

def minimum_squares(L, B):
    a = math.gcd(L, B)
    N = (L * B) // (a * a)
    K = a
    return (N, K)

def determine_winner(n, m1, m2):
    if m1 == 0:
        return 1

    x = n % (m1 + m2)

    if x < m1:
        return 0
    elif x == m1 or x >= m2:
        return 1
    else:
        return 1 if (x // m1) % 2 == 1 else 0

def minimum_moves_to_reach_last_block(N, heights):
    if heights[0] < max(heights):
        return -1

    stack = []
    for i in range(1, N):
        if len(stack) == 0 or heights[i] < stack[-1]:
            stack.append(heights[i])
        else:
            while len(stack) > 0 and stack[-1] <= heights[i]:
                stack.pop()
            stack.append(heights[i])

    return len(stack)

def calculate_total_completed_poses(classroom, poses):
