                    total_poses += 1
    return total_poses

def matrix_diagonally(mat):
    n = len(mat)
    m = len(mat[0])
    diagonals = [[] for _ in range(n + m - 1)]

    for i in range(n):
        for j in range(m):
            sum_index = i + j
            if sum_index % 2 == 0:
                diagonals[sum_index].insert(0, mat[i][j])
            else:
                diagonals[sum_index].append(mat[i][j])

    result = []
    for diagonal in diagonals:
        result.extend(diagonal)

    return result

