        p = 2
        m = 0
        while p < n:
            m += 1
            p *= 2
        p //= 2
        return 2 * (n - p) + 1

def calculate_race_statistics(race_results):
    def get_time(s):
        (hh, mm, ss) = [int(v) for v in s.split('|')]
        return hh * 3600 + mm * 60 + ss

    def format_time(time):
        hh = time // 3600
        mm = time // 60 % 60
        ss = time % 60
        return '{hh:02d}|{mm:02d}|{ss:02d}'.format(**locals())

    def get_range(times):
        return times[-1] - times[0]

    def get_average(times):
        return sum(times) // len(times)

    def get_median(times):
        middle = len(times) >> 1
        return times[middle] if len(times) & 1 else (times[middle - 1] + times[middle]) // 2

    if race_results == '':
        return race_results

    times = [get_time(s) for s in race_results.split(', ')]
    times.sort()
    rng = format_time(get_range(times))
    avg = format_time(get_average(times))
    mdn = format_time(get_median(times))
    return 'Range: {rng} Average: {avg} Median: {mdn}'.format(**locals())

from collections import defaultdict

def min_removals_to_make_good_sequence(sequence):
    arr = defaultdict(int)
    for num in sequence:
        arr[num] += 1

    powers = [1 << i for i in range(32)]
    count = 0

    for num, freq in list(arr.items()):
        good = False
        for p in powers:
            complement = p - num
            if complement == num:
                if arr[complement] > 1:
                    good = True
                    break
            elif arr.get(complement):
                good = True
                break
        if not good:
            count += freq

    return count

def unique_prime_factors(n):
    count = 0
    i = 2
    while i ** 2 <= n:
        if n % i == 0:
            count += 1
            while n % i == 0:
                n //= i
        i += 1
    if n != 1:
        count += 1
    return count

def max_columns_for_tiling(N, M):
    prm_fac = unique_prime_factors(M)
    ans = 0
    i = prm_fac
    while i > 0:
        if N % i == 0:
            ans = i
            break
        i -= 1
    return ans

def find_mayor_amidakuji(n, m, a, horizontal_lines):
    # Sort horizontal lines by height in descending order
    horizontal_lines.sort(key=lambda x: x[0], reverse=True)

    # Initialize the current vertical line position
    current_line = a

    # Process each horizontal line
    for line in horizontal_lines:
        if line[1] == current_line:
            current_line = line[2]
        elif line[2] == current_line:
            current_line = line[1]

    # Return the final position of the vertical line
    return current_line

