def calculate_max_points(n, m, banned_cells):
    row_blocked = defaultdict(bool)
    col_blocked = defaultdict(bool)

    for (x, y) in banned_cells:
        row_blocked[x] = True
        col_blocked[y] = True

    ans = 0
    for i in range(2, n):
        if not row_blocked[i]:
            ans += 1
        if not col_blocked[i]:
            ans += 1

    if n % 2:
        if not row_blocked[n // 2 + 1] and not col_blocked[n // 2 + 1]:
            ans -= 1

    return ans

def generate_carpet_layout(N, K):
    if N == 0 and K == 0:
        return []

    if N & 1 or K >= 1 << (N >> 1):
        return "No"

    arr = [[-1 for _ in range(N)] for _ in range(N)]
    k_minus_1 = K - 1
    n_minus_1 = N - 1

    for c in range(N):
        arr[0][c] = k_minus_1 >> (n_minus_1 - c >> 1) & 1

    mv = ((-1, 0), (0, 1), (1, 0), (0, -1))
    d2c = {0: '.', 1: 'E'}

    for r in range(n_minus_1):
        for c in range(N):
            f = 0
            t = arr[r][c]
            for i in range(4):
                nr, nc = r + mv[i][0], c + mv[i][1]
                if 0 <= nr < N and 0 <= nc < N and arr[nr][nc] == t:
                    f += 1
            arr[r + 1][c] = 1 - t if f == 2 else t

    layout = [''.join([d2c[arr[r][c]] for c in range(N)]) for r in range(N)]
    return layout

def maximize_expression_value(expression: str) -> int:
    d = list(expression.split('*'))
    last = 0
    po = []
    ki = []

    for i in range(len(d)):
        po.append(last)
        ki.append(len(d[i]) + last)
        last += len(d[i]) + 1

    ans = [eval(expression)]

    for a in po:
        for b in ki:
            if a > b - 2:
                continue
            x = expression[:a] + '(' + expression[a:b] + ')' + expression[b:]
            ans.append(eval(x))

    return max(ans)

