from collections import deque

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def tree_serialization(root):
    if root is None:
        return []

    ans = []
    queue = deque([root])

    while queue:
        node = queue.popleft()
        if node is None:
            ans.append(None)
        else:
            ans.append(node.data)
            queue.append(node.left)
            queue.append(node.right)

    while ans and ans[-1] is None:
        ans.pop()

    return ans

def tree_deserialization(serialized_list):
    if not serialized_list:
        return None

    root = Node(serialized_list[0])
    queue = deque([root])
    index = 1

    while queue and index < len(serialized_list):
        node = queue.popleft()

        if serialized_list[index] is not None:
            node.left = Node(serialized_list[index])
            queue.append(node.left)

        index += 1

        if index < len(serialized_list) and serialized_list[index] is not None:
            node.right = Node(serialized_list[index])
            queue.append(node.right)

        index += 1

    return root

def execute_shell_commands(commands):
    def pwd(cur):
        if len(cur) == 0:
            return '/'
        else:
            return '/' + '/'.join(cur) + '/'

    def process(cmd, cur):
        cmd = cmd[3:]
        ds = cmd.split('/')
        if cmd.startswith('/'):
            cur = []
        for d in ds:
            if d == '..':
                if cur:
                    cur.pop()
            elif d and d != '.':
                cur.append(d)
        return cur

    cur = []
    output = []
    for cmd in commands:
        if cmd == 'pwd':
            output.append(pwd(cur))
        else:
            cur = process(cmd, cur)
    return output

def count_unused_edges(N, M, edges):
    import heapq

    # Initialize the graph with infinity distances
    graph = [[float('inf')] * (N + 1) for _ in range(N + 1)]

    # Fill the graph with edge weights
    for a, b, c in edges:
        graph[a][b] = c
        graph[b][a] = c

    def dijkstra(start, cost):
        distances = [float('inf')] * (N + 1)
        distances[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_vertex = heapq.heappop(priority_queue)

            if current_distance > distances[current_vertex]:
                continue

            for neighbor in range(1, N + 1):
                if cost[current_vertex][neighbor] == float('inf'):
                    continue

                distance = current_distance + cost[current_vertex][neighbor]

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return distances

    unused_edges_count = 0

    for i in range(1, N):
        shortest_paths = dijkstra(i, graph)
        for j in range(i + 1, N + 1):
            if graph[i][j] != float('inf') and graph[i][j] > shortest_paths[j]:
                unused_edges_count += 1

    return unused_edges_count

