INF = 10 ** 20

def update_state(state, newx):
    tmp = list(state)
    tmp[newx] = 1
    return tuple(tmp)

def get_co(x, y, formation):
    dc = do = 0
    score = formation[y][x]
    if score < 0:
        dc = -score
    else:
        do = score
    return (dc, do)

def minimum_cost(x, y, state, ox, goal, dic, w, m, formation):
    if (x, y, state, ox) in dic:
        return dic[x, y, state, ox]
    if y == goal:
        return 0
    if ox <= 1:
        return INF
    ret = INF
    if x >= 1:
        if state[x - 1] == 0:
            (dc, do) = get_co(x - 1, y, formation)
            ret = min(ret, minimum_cost(x - 1, y, update_state(state, x - 1), min(ox + do - 1, m), goal, dic, w, m, formation) + dc)
        else:
            ret = min(ret, minimum_cost(x - 1, y, state, ox - 1, goal, dic, w, m, formation))
    if x < w - 1:
        if state[x + 1] == 0:
            (dc, do) = get_co(x + 1, y, formation)
            ret = min(ret, minimum_cost(x + 1, y, update_state(state, x + 1), min(ox + do - 1, m), goal, dic, w, m, formation) + dc)
        else:
            ret = min(ret, minimum_cost(x + 1, y, state, ox - 1, goal, dic, w, m, formation))
    (dc, do) = get_co(x, y + 1, formation)
    ret = min(ret, minimum_cost(x, y + 1, tuple((1 if i == x else 0 for i in range(w))), min(ox + do - 1, m), goal, dic, w, m, formation) + dc)
    dic[x, y, state, ox] = ret
    return ret

def calculate_minimum_cost(W, H, f, m, o, formation):
    if o <= 1:
        return 'NA'
    dic = {}
    ans = INF
    for i in range(W):
        (dc, do) = get_co(i, 0, formation)
        state = tuple((1 if i == j else 0 for j in range(W)))
        ans = min(ans, minimum_cost(i, 0, state, min(o + do - 1, m), H - 1, dic, W, m, formation) + dc)
    if ans > f:
        return 'NA'
    else:
        return str(ans)

def minimum_cost(cost, N, W):
    def go(ind, currw):
        if currw > W:
            return 10 ** 18
        if ind == N:
            if currw == W:
                return 0
            return 10 ** 18
        if dp[ind][currw] != -1:
            return dp[ind][currw]
        c1 = 10 ** 18
        if cost[ind] != -1:
            c1 = cost[ind] + go(ind, currw + ind + 1)
        c2 = go(ind + 1, currw)
        ans = min(c1, c2)
        dp[ind][currw] = ans
        return ans

    dp = [[-1] * (W + 1) for _ in range(N)]
    ans1 = go(0, 0)
    if ans1 == 10 ** 18:
        return -1
    return ans1

def perform_set_mutations(A, operations):
    for operation, elements in operations:
        if operation == "update":
            A.update(elements)
        elif operation == "intersection_update":
            A.intersection_update(elements)
        elif operation == "difference_update":
            A.difference_update(elements)
        elif operation == "symmetric_difference_update":
            A.symmetric_difference_update(elements)
    return sum(A)

