from collections import defaultdict, deque

def min_moves_to_opposite_parity(n, arr):
    d = [-1] * n
    parity = [x % 2 for x in arr]
    done = deque()
    lrs = defaultdict(list)

    for i in range(n):
        put = False
        if i - arr[i] >= 0:
            if parity[i] != parity[i - arr[i]]:
                d[i] = 1
                done.append(i)
                put = True
            lrs[i - arr[i]].append(i)
        if i + arr[i] < n:
            if not put and parity[i] != parity[i + arr[i]]:
                d[i] = 1
                done.append(i)
            lrs[i + arr[i]].append(i)

    while done:
        i = done.popleft()
        for j in lrs[i]:
            if d[j] == -1:
                d[j] = d[i] + 1
                done.append(j)

    return d

def count_consecutive_sum_solutions(num):
    upper_limit = 1
    while True:
        if upper_limit * (upper_limit + 1) // 2 > num:
            break
        upper_limit += 1

    return sum([1 if i % 2 and (not num % i) else 1 if not i % 2 and num % i == i // 2 else 0 for i in range(1, upper_limit)])

