def calculate_minimum_score(n: int, m: int, k: int) -> int:
    MOD = 1000000009

    x = m - (n // k * (k - 1) + n % k)

    if x <= 0:
        return m % MOD

    return (m - x + (pow(2, x + 1, MOD) + 2 * MOD - 2) * k - x * (k - 1)) % MOD

