        adjacency_list[b - 1].append(a - 1)

    # Check if there is a path from Island 1 to Island N using two boat services
    for i in adjacency_list[0]:
        for j in adjacency_list[i]:
            if j == N - 1:
                return "POSSIBLE"

    return "IMPOSSIBLE"

