def count_divisors_of_factorial(N):
    primes = [True] * (N + 1)
    prime_factors = []

    for i in range(2, N + 1):
        if primes[i]:
            j = i * i
            while j <= N:
                primes[j] = False
                j += i
            k = i
            count = 0
            while k <= N:
                count += N // k
                k *= i
            prime_factors.append(count)

    total_divisors = 1
    for count in prime_factors:
        total_divisors *= count + 1

    return total_divisors

def min_modifications_for_unique_subarray_sums(N, K, A):
    ans = 0
    for i in range(K):
        d = {}
        q = i
        while q < N:
            if A[q] not in d:
                d[A[q]] = 1
            else:
                d[A[q]] += 1
            q += K
        l = list(d.values())
        s = sum(l)
        mx = max(l)
        ans += s - mx
    return ans

def calculate_flagstones(n: int, m: int, a: int) -> int:
