def hill_jumping_competition(heights, operations):
    results = []

    for op in operations:
        if op[0] == 1:
            # Type 1 operation: Jump from hill i for k times
            i, k = op[1] - 1, op[2]
            step = i
            for _ in range(k):
                temp = 0
                j = 1
                while j <= 100 and temp == 0 and (step + j < len(heights)):
                    if heights[step + j] > heights[step]:
                        step = step + j
                        temp = 1
                    j += 1
            results.append(step + 1)

        elif op[0] == 2:
            # Type 2 operation: Update heights from L to R by X
            L, R, X = op[1] - 1, op[2] - 1, op[3]
            for idx in range(L, R + 1):
                heights[idx] += X

    return results

def calculate_max_hedgehog_beauty(n, m, segments):
    values = [1] * n
    nodes = [list() for _ in range(n)]
    spikes = [0] * n

    for (u, v) in segments:
        if u > v:
            u, v = v, u
        nodes[u - 1].append(v - 1)
        spikes[u - 1] += 1
        spikes[v - 1] += 1

    for i in range(n):
        for node in nodes[i]:
            values[node] = max(values[node], values[i] + 1)

    m = max(range(n), key=lambda i: spikes[i] * values[i])
    return spikes[m] * values[m]

def count_valid_paintings(H, W, A):
    mod = 998244353

    # Precompute factorials and their inverses
    FACT = [1]
    for i in range(1, 21):
        FACT.append(FACT[-1] * i % mod)
    FACT_INV = [pow(FACT[-1], mod - 2, mod)]
    for i in range(20, 0, -1):
        FACT_INV.append(FACT_INV[-1] * i % mod)
    FACT_INV.reverse()

    # Precompute combinations
    COMBI = [[-1] * 21 for i in range(21)]
    def Combi(a, b):
        if COMBI[a][b] != -1:
            return COMBI[a][b]
        if 0 <= b <= a:
            COMBI[a][b] = FACT[a] * FACT_INV[b] * FACT_INV[a - b] % mod
            return COMBI[a][b]
        else:
            COMBI[a][b] = 0
            return 0

    # Precompute rectangle counts
    M = max(H, W) + 1
    RA = [[-1] * M for i in range(M)]
    def rect(H, W):
        if H == W == 0:
            return 1
        if RA[H][W] != -1:
            return RA[H][W]
        DP = [[[0, 0] for j in range(W + 1)] for i in range(H + 1)]
        DP[0][0][0] = 1
        DP[0][0][1] = 1
        for h in range(H + 1):
            for w in range(W + 1):
                for nexth in range(h + 1, H + 1):
                    DP[nexth][w][0] += DP[h][w][1] * FACT_INV[nexth - h]
                    DP[nexth][w][0] %= mod
                for nextw in range(w + 1, W + 1):
                    DP[h][nextw][1] += DP[h][w][0] * FACT_INV[nextw - w]
                    DP[h][nextw][1] %= mod
        RA[H][W] = RA[W][H] = sum(DP[H][W]) % mod * FACT[H] * FACT[W] % mod
        return RA[H][W]

    # Precompute calculations
    CA = [[-1] * (W + 1) for i in range(H + 1)]
    def calc(h, w):
        if CA[h][w] != -1:
            return CA[h][w]
        RET = 0
        for bh in range(h + 1):
            for bw in range(w + 1):
                RET += rect(bh, w - bw) * rect(h - bh, bw) * Combi(h, bh) * Combi(w, bw)
                RET %= mod
        CA[h][w] = RET % mod
        return CA[h][w]

    for i in range(H + 1):
        for j in range(W + 1):
            calc(i, j)

    ANS = rect(H, W)
    for i in range((1 << H) - 1):
        for j in range((1 << W) - 1):
            okflag = 1
            for h in range(H):
                if i & 1 << h != 0:
                    continue
                coinc = ''
                dif = 0
                for w in range(W):
                    if j & 1 << w != 0:
                        continue
                    if coinc == '':
                        coinc = A[h][w]
                    elif A[h][w] != coinc:
                        dif = 1
                        break
                if dif == 0:
                    okflag = 0
                    break
            if okflag == 0:
                continue
            okflag = 1
            for w in range(W):
                if j & 1 << w != 0:
                    continue
                coinc = ''
                dif = 0
                for h in range(H):
                    if i & 1 << h != 0:
                        continue
                    if coinc == '':
                        coinc = A[h][w]
                    elif A[h][w] != coinc:
                        dif = 1
                        break
                if dif == 0:
                    okflag = 0
                    break
            if okflag == 0:
                continue
            HR = WR = 0
            for h in range(H):
                if i & 1 << h != 0:
                    HR += 1
            for w in range(W):
                if j & 1 << w != 0:
                    WR += 1
            ANS += CA[HR][WR]

    return ANS % mod

