from collections import deque

def validate_and_construct_board(n, data):
    res = [[''] * n for _ in range(n)]
    q = deque()

    # Initialize the queue with all cells that are blocked zones (X)
    for i in range(n):
        for j in range(n):
            if data[i][j] == (i, j):
                q.append((i, j))
                res[i][j] = 'X'

    # Process the queue to fill in the directions
    while q:
        (i, j) = q.popleft()
        if 0 <= i + 1 < n and 0 <= j < n and (data[i + 1][j] == data[i][j]) and (not res[i + 1][j]):
            res[i + 1][j] = 'U'
            q.append((i + 1, j))
        if 0 <= i - 1 < n and 0 <= j < n and (data[i - 1][j] == data[i][j]) and (not res[i - 1][j]):
            res[i - 1][j] = 'D'
            q.append((i - 1, j))
        if 0 <= i < n and 0 <= j + 1 < n and (data[i][j + 1] == data[i][j]) and (not res[i][j + 1]):
            res[i][j + 1] = 'L'
            q.append((i, j + 1))
        if 0 <= i < n and 0 <= j - 1 < n and (data[i][j - 1] == data[i][j]) and (not res[i][j - 1]):
            res[i][j - 1] = 'R'
            q.append((i, j - 1))

    # Handle cells that lead to infinite loops
    for i in range(n):
        for j in range(n):
            if data[i][j] == (-1, -1):
                if 0 <= i + 1 < n and 0 <= j < n and (data[i + 1][j] == (-1, -1)):
                    res[i][j] = 'D'
                elif 0 <= i - 1 < n and 0 <= j < n and (data[i - 1][j] == (-1, -1)):
                    res[i][j] = 'U'
                elif 0 <= i < n and 0 <= j + 1 < n and (data[i][j + 1] == (-1, -1)):
                    res[i][j] = 'R'
                elif 0 <= i < n and 0 <= j - 1 < n and (data[i][j - 1] == (-1, -1)):
                    res[i][j] = 'L'
                else:
                    return "INVALID", None

    # Check if any cell is still empty
    for row in res:
        if '' in row:
            return "INVALID", None

    return "VALID", res

def min_operations_to_delete_string(s: str, n: int = None) -> int:
    if n is None:
        n = len(s)

    # Preprocess the string to remove consecutive duplicates
    ss = ''
    re = ''
    for i in range(n):
        if re != s[i]:
            ss += re
            re = s[i]
    ss += re

    a = ss
    N = len(a)

    # Initialize the dp array
    dp = [[0 for _ in range(N + 1)] for _ in range(N + 1)]

    # Fill the dp array
    for l in range(1, N + 1):
        i = 0
        j = l - 1
        while j < N:
            if l == 1:
                dp[i][j] = 1
            else:
                dp[i][j] = 1 + dp[i + 1][j]
                for K in range(i + 1, j + 1):
                    if a[i] == a[K]:
                        if dp[i][j] >= dp[i][K - 1] + dp[K + 1][j]:
                            dp[i][j] = dp[i][K - 1] + dp[K + 1][j]
            i += 1
            j += 1

    return dp[0][N - 1]

