    dp = [[[0, 0] for j in range(i + 2)] for i in range(N + 1)]
    dp[0][0][1] = 1

    for i in range(1, N + 1):
        for j in range(i + 1):
            dp[i][j][0] += 2 ** j * dp[i - 1][j][0]
            if j:
                dp[i][j][0] += dp[i - 1][j - 1][0]
            odd = 2 ** (j - 1) if j else 0
            even = 2 ** j - odd
            if bink[i - 1] == 1:
                dp[i][j][0] += even * dp[i - 1][j][1]
            if bink[i - 1] == 0:
                dp[i][j][1] += even * dp[i - 1][j][1]
            else:
                dp[i][j][1] += odd * dp[i - 1][j][1]
                if j:
                    dp[i][j][1] += dp[i - 1][j - 1][1]

    ans = sum(map(sum, dp[-1]))
    return ans % MOD

def min_absolute_difference_modulo(n, p, k_list):
    MOD = 10 ** 9 + 7

    if p == 1:
        return len(k_list) % 2

    k_list.sort(reverse=True)
    left = Counter()
    right = Counter()

    for k in k_list:
        if not left:
            left[k] += 1
        else:
            if k in left:
                del left[k]
                continue
            right[k] += 1
            while True:
                (q, r) = divmod(right[k], p)
                right[k] = r
                right[k + 1] += q
                if q == 0:
                    break
                if k + 1 in left:
                    assert right[k + 1] == 1
                    del left[k + 1]
                    del right[k + 1]
                    break
                k += 1

    right_sum = sum((v * pow(p, k, MOD) for (k, v) in right.items())) % MOD

    if not left:
        return right_sum

    left_sum = sum((v * pow(p, k, MOD) for (k, v) in left.items())) % MOD

    return (left_sum - right_sum) % MOD

