    def snek(n):
        even = 0
        odd = 0
        while n % 2 == 0:
            n //= 2
            even += 1
        for j in range(3, int(n ** 0.5) + 1, 2):
            if n % j == 0:
                while n % j == 0:
                    n //= j
                    odd += 1
