MOD = 998244353

def power(a, b):
    res = 1
    while b > 0:
        if b % 2 == 1:
            res = res * a % MOD
        a = a * a % MOD
        b //= 2
    return res

def inverse(n):
    return power(n, MOD - 2)

def calculate_board_value(n, m, grid):
    prob = [0, 0]
    for c in range(2, max(n, m) + 1):
        prob.append(prob[-1] + (-1) ** c * inverse(power(2, c)))
        prob[-1] %= MOD

    res = 0

    # Process rows
    for r in range(n):
        cnt = 0
        for c in range(m):
            if grid[r][c] == 'o':
                cnt += 1
            else:
                cnt = 0
            res += prob[cnt]
            res %= MOD

    # Process columns
    for c in range(m):
        cnt = 0
        for r in range(n):
            if grid[r][c] == 'o':
                cnt += 1
            else:
                cnt = 0
            res += prob[cnt]
            res %= MOD

    # Multiply by 2 for each white cell
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'o':
                res *= 2
                res %= MOD

    return res

